    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (min > matr[i][j]) {
                min = matr[i][j];
                min_i = i;
            }
            if (max < matr[i][j]) {
                max = matr[i][j];
                max_i = i;
            }
        }
    }
    int *temp;
    temp = matr[min_i];
    matr[min_i] = matr[max_i];
    matr[max_i] = temp;
}

