        *res = 0;
}

void output (int **data, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j < n - 1)
                printf("%d ", data[i][j]);
            else if (j == n - 1 && i < n - 1)
                printf("%d\n", data[i][j]);
            else
                printf("%d", data[i][j]);
        }
    }
}

void make_spiral(int **spiral, int n) {
    int count = 1;
    for (int k = 0; k < (n + 1) / 2; k++) {
        for (int i = k; i < n - k; i++) {
            spiral[k][i] = count;
            count++;
        }
        for (int i = k + 1; i < n - k; i++) {
            spiral[i][n - k- 1] = count;
            count++;
        }
        for (int i = n - k - 2; i >= k; i--) {
            spiral[n - k - 1][i] = count;
            count++;
        }
        for (int i = n - k - 2; i >= k + 1; i--) {
            spiral[i][k] = count;
            count++;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("n/a");
        return 0;
    }
    int **a = malloc(n * sizeof(int*));
    for (int i = 0; i < n; i++) a[i] = malloc(n * sizeof(int));

    int val = 0;
    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    while (top <= bottom && left <= right) {
        // Down along left column
        for (int i = top; i <= bottom; i++) a[i][left] = val * val, val++;
        left++;
        // Right along bottom row
        for (int j = left; j <= right; j++) a[bottom][j] = val * val, val++;
        bottom--;
        // Up along right column
        if (left <= right) {
            for (int i = bottom; i >= top; i--) a[i][right] = val * val, val++;
            right--;
        }
        // Left along top row
        if (top <= bottom) {
            for (int j = right; j >= left; j--) a[top][j] = val * val, val++;
            top++;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j == n - 1) printf("%d", a[i][j]);
            else printf("%d ", a[i][j]);
        }
        if (i < n - 1) printf("\n");
        free(a[i]);
    }
    free(a);
    return 0;
}

