    if (!fgets(s, sizeof(s), stdin) || !fgets(sub, sizeof(sub), stdin)) {
        printf("n/a");
        return 0;
    }
    int len_s = strlen(s);
    if (len_s > 0 && s[len_s - 1] == '\n') s[--len_s] = '\0';
    int len_sub = strlen(sub);
    if (len_sub > 0 && sub[len_sub - 1] == '\n') sub[--len_sub] = '\0';

    if (len_sub == 0) {
        printf("%s", s);
        return 0;
    }

    char *last = NULL;
    char *cur = s;
    while ((cur = strstr(cur, sub)) != NULL) {
        last = cur;
        cur += 1;
    }

    if (last != NULL) {
        char res[2000];
        int idx = last - s;
        strncpy(res, s, idx);
        res[idx] = '\0';
        strcat(res, last + len_sub);
        printf("%s", res);
    } else {
        printf("%s", s);
    }
    return 0;
}

